mapper.select:
select digitalId, digitalname, digitalbrand, digitalimg, digitalsoc, release_time, digitalprice, digitalscreen, digitalbattery, digitalcamera, type from phone


        phone.digitalname like concat('%',#{digitalname},'%')


        and phone.digitalbrand = #{digitalbrand}


        and phone.type = #{type}


        and phone.release_time between #{begin} and #{end}


        and phone.digitalprice between #{min} and #{max}
